<?php
require_once __DIR__.'/includes/appointment_helpers.php';
if(!is_logged_in()||($_SESSION['role']??'')!=='doctor'){header('Location: login.php');exit;}
$doctorId=(int)$_SESSION['user_id'];if(!doctor_is_approved($pdo,$doctorId)){http_response_code(403);exit('Doctor account not approved.');}
$days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='add'){$day=filter_var($_POST['weekday']??null,FILTER_VALIDATE_INT);$start=$_POST['start_time']??'';$end=$_POST['end_time']??'';
  if($day===false||$day<0||$day>6)$errors[]='Choose a valid weekday.';
  if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$start)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$end)||$start>=$end)$errors[]='Enter a valid time range.';
  if(!$errors){$s=$pdo->prepare('SELECT id FROM doctor_availability WHERE doctor_id=? AND weekday=? AND is_available=1 AND start_time<? AND end_time>?');$s->execute([$doctorId,$day,$end,$start]);if($s->fetch())$errors[]='This period overlaps an existing availability period.';else{$s=$pdo->prepare('INSERT INTO doctor_availability(doctor_id,weekday,start_time,end_time) VALUES(?,?,?,?)');$s->execute([$doctorId,$day,$start,$end]);flash('Availability added.');header('Location: doctor_availability.php');exit;}}
 }elseif($action==='delete'){$id=filter_var($_POST['availability_id']??null,FILTER_VALIDATE_INT);if($id){$s=$pdo->prepare('DELETE FROM doctor_availability WHERE id=? AND doctor_id=?');$s->execute([$id,$doctorId]);flash('Availability removed.');header('Location: doctor_availability.php');exit;}}
}
$s=$pdo->prepare('SELECT id,weekday,start_time,end_time FROM doctor_availability WHERE doctor_id=? ORDER BY weekday,start_time');$s->execute([$doctorId]);$rows=$s->fetchAll();$notice=get_flash();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My availability | MediConnect</title><link rel="stylesheet" href="assets/css/auth.css"></head><body><main class="dashboard-shell"><header class="dashboard-header"><a class="brand" href="doctor_dashboard.php">✚ MediConnect</a><a href="doctor_appointments.php">Appointments</a></header><section class="welcome-panel"><h1>My availability</h1><p class="muted">Set weekly consultation periods. Patients will see 30-minute appointment start times.</p></section>
<?php if($notice):?><div class="alert success"><?=e($notice['message'])?></div><?php endif;?><?php if($errors):?><div class="alert error"><?php foreach($errors as $x):?><p><?=e($x)?></p><?php endforeach;?></div><?php endif;?>
<section class="profile-panel"><h2>Add availability</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Weekday<select name="weekday"><?php foreach($days as $i=>$day):?><option value="<?=$i?>"><?=e($day)?></option><?php endforeach;?></select></label><div class="form-grid"><label>Start<input type="time" name="start_time" required></label><label>End<input type="time" name="end_time" required></label></div><button class="primary-button">Add period</button></form></section>
<section class="profile-panel"><h2>Current weekly schedule</h2><?php if(!$rows):?><p>No availability has been added.</p><?php endif;?><?php foreach($rows as $r):?><div class="schedule-row"><span><b><?=e($days[(int)$r['weekday']])?></b> · <?=e(substr($r['start_time'],0,5))?>–<?=e(substr($r['end_time'],0,5))?></span><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="availability_id" value="<?=(int)$r['id']?>"><button class="secondary-button">Remove</button></form></div><?php endforeach;?></section></main></body></html>
